/**
 * Request ID correlation (feature #108 — "Structured request logging with
 * correlation/request IDs").
 *
 * ## Generation + log attachment (step 1)
 *
 * The actual per-request ID is generated by Fastify itself: `../index.ts`'s
 * `buildApp()` passes a `genReqId` option (`() => randomUUID()`) to the
 * `Fastify(...)` constructor, so every incoming request gets a fresh v4
 * UUID as `request.id` before any hook — this module's included — ever
 * runs. Nothing here needs to (re-)attach that ID to log lines either:
 * Fastify's own pino integration already derives `request.log` as a child
 * logger with the request's ID bound under the `reqId` field (see
 * `fastify/lib/logger-factory.js`'s `createChildLogger`), so every line any
 * handler or hook emits via `request.log.*` — including the built-in
 * "incoming request"/"request completed" lines and
 * `./error-handler.ts`'s `request.log.error(...)` call — automatically
 * carries the same `reqId` for that request's entire lifecycle, with zero
 * extra wiring. This module's only job is step 2 below.
 *
 * ## Response header (step 2)
 *
 * {@link registerRequestId} adds a single `onSend` hook that echoes
 * `request.id` back as the {@link REQUEST_ID_HEADER} response header, so a
 * client (or an operator correlating a support ticket to server-side logs)
 * can read the same ID that tags every log line the request produced.
 * `onSend` — rather than `onRequest`, used by `./session.ts`/`./csrf.ts` —
 * is deliberate here: it is Fastify's last hook before a reply is actually
 * written to the wire, and it still runs for a reply produced by
 * `./error-handler.ts`'s error handler or Fastify's own not-found handler,
 * so the header is present on every response this instance ever sends, not
 * just the happy path. Registration order relative to the other hooks in
 * `../index.ts`'s `buildApp()` therefore does not matter — `onSend` hooks
 * only race each other, and this is the only one that touches this header.
 */
import type { ApiGatewayApp } from "../index.js";

/** Response header {@link registerRequestId} echoes the generated per-request ID (`request.id`) back on. Lower-case, matching Node's own header-name normalization. */
export const REQUEST_ID_HEADER = "x-request-id";

/**
 * Wire the {@link REQUEST_ID_HEADER} response header onto `app` (step 2).
 * Safe to call at any point in `buildApp()`'s setup relative to the other
 * `registerX(built)` calls — see this module's docs on why `onSend`
 * ordering doesn't matter here.
 */
export function registerRequestId(app: ApiGatewayApp): void {
  app.addHook("onSend", async (request, reply) => {
    reply.header(REQUEST_ID_HEADER, request.id);
  });
}
